/** Social preview card shared by every page (generated by scripts/gen-assets.ts). */
export const OG_IMAGE = {
  // ?v=2 makes sharing sites fetch the card with the new logo instead of a cached copy of the old one.
  path: "/og.png?v=3",
  width: 1200,
  height: 630,
  alt: "ipcomet: free, private network tools. What is my IP address?",
};

/** Square brand logo used as the publisher logo in structured data. */
export const LOGO_PATH = "/icon-512.png";

/** The person who builds and maintains the site. Named on the About page and as the author of every guide. */
export const AUTHOR = "Ishant Singh";
export const AUTHOR_ID = "/about#ishant-singh";
export const CONTACT_EMAIL = "hello@ipcomet.com";

export const personJsonLd = (origin: string) =>
  origin
    ? {
        "@context": "https://schema.org",
        "@type": "Person",
        "@id": origin + AUTHOR_ID,
        name: AUTHOR,
        url: origin + "/about",
        sameAs: ["https://github.com/Ishant-Singh-Dev"],
        worksFor: { "@id": origin + "/#organization" },
      }
    : null;

export const organizationJsonLd = (origin: string) =>
  origin
    ? {
        "@context": "https://schema.org",
        "@type": "Organization",
        "@id": origin + "/#organization",
        name: BRAND,
        url: origin + "/",
        logo: { "@type": "ImageObject", url: origin + LOGO_PATH, width: 512, height: 512 },
        founder: { "@type": "Person", "@id": origin + AUTHOR_ID, name: AUTHOR, url: origin + "/about" },
        email: CONTACT_EMAIL,
        contactPoint: {
          "@type": "ContactPoint",
          contactType: "customer support",
          email: CONTACT_EMAIL,
          availableLanguage: ["en", "fr", "es", "pt", "de", "hi"],
        },
        sameAs: [
          "https://github.com/Ishant-Singh-Dev/ipcomet-frontend",
          "https://github.com/Ishant-Singh-Dev",
        ],
      }
    : null;

