/** The icon and wordmark together (static/logo.svg, built by scripts/gen-assets.ts). Its alt text is the brand name. */
const LOGO = `<img src="/logo.svg" width="127" height="34" alt="${BRAND}" decoding="async">`;
const BURGER = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>`;

/** Drops whitespace that sits between two tags and contains a line break. */
const minify = (s: string) => s.replace(/>\s*\n\s*</g, "><");

export interface PageOptions {
  id: string;
  title: string;
  description: string;
  /** Absolute site origin, or "" when unknown (canonical and og:url are then omitted). */
  origin: string;
  path: string;
  body: string;
  jsonLd?: unknown[];
  noindex?: boolean;
  ogType?: "website" | "article";
  /** Language of the page, English by default. `path` is always the English path; the prefix is added here. */
  locale?: Locale;
  /** Languages this exact page exists in. Drives hreflang and the language switcher. Omit for English-only pages. */
  altLocales?: Locale[];
}

export const jsonLdScripts = (items: unknown[] = []) =>
  items
    .filter(Boolean)
    .map((i) => `<script type="application/ld+json">${JSON.stringify(i).replace(/</g, "\\u003c")}</script>`)
    .join("");

export function renderPage(o: PageOptions): string {
  const loc: Locale = o.locale ?? "en";
  const meta = LOCALE_META[loc];
  const lt = (text: string, vars?: Record<string, string | number>) => t(loc, text, vars);
  const lp = (path: string) => localizedPath(loc, path);
  const pagePath = lp(o.path);
  const url = o.origin ? o.origin + pagePath : "";
  const full = `${o.title} | ${BRAND}`;
  const title = full.length > 60 ? o.title : full;
  const active = (id: string) => (id === o.id ? ' aria-current="page"' : "");

  const tools = TOOLS.map((x) => localTool(x, loc));
  const main = ["lookup", "dns", "whois", "speed"].map((id) => tools.find((x) => x.id === id)!);
  const dnav =
    main.map((x) => `<a href="${lp(x.path)}"${active(x.id)}>${esc(x.name)}</a>`).join("") +
    `<details class="menu"><summary class="nl">${esc(lt("All tools"))}</summary><div class="mega">${tools
      .map((x) => `<a href="${lp(x.path)}"><b>${esc(x.name)}</b><span>${esc(x.desc)}</span></a>`)
      .join("")}</div></details><a href="/learn"${o.id === "learn" ? ' aria-current="page"' : ""}>${esc(lt("Learn"))}</a>`;

  // Language switcher: the same page in another language when it exists, otherwise that language's home page.
  const available = new Set(o.altLocales ?? ["en"]);
  const languages = activeLocales();
  const switchHref = (l: Locale) => localizedPath(l, available.has(l) ? o.path : "/");
  const langLink = (l: Locale) =>
    `<a href="${switchHref(l)}" hreflang="${LOCALE_META[l].hreflang}" lang="${LOCALE_META[l].htmlLang}"${l === loc ? ' aria-current="true"' : ""}>${esc(LOCALE_META[l].native)}</a>`;
  const langMenu =
    languages.length > 1
      ? `<details class="menu dlang"><summary class="nl" aria-label="${esc(lt("Language"))}">${esc(meta.native)}</summary><div class="mega">${languages.map(langLink).join("")}</div></details>`
      : "";
  const drawerLangs = languages.length > 1 ? `<h5>${esc(lt("Language"))}</h5>${languages.map(langLink).join("")}` : "";
  const footerLangs = languages.length > 1 ? `<nav class="langrow" aria-label="${esc(lt("Language"))}">${languages.map(langLink).join("")}</nav>` : "";

  const drawer = tools.map((x) => `<a href="${lp(x.path)}">${esc(x.name)}</a>`).join("") + `<a href="/learn">${esc(lt("Learn"))}</a>` + drawerLangs;

  const footerTools = tools.map((x) => `<li><a href="${lp(x.path)}">${esc(x.name)}</a></li>`).join("");
  const footerLearn = ARTICLES.slice(0, 6)
    .map((a) => `<li><a href="/learn/${a.slug}"${loc === "en" ? "" : ' hreflang="en" lang="en"'}>${esc(a.title.replace(/:.*$/, "").replace(/ \(.*\)$/, ""))}</a></li>`)
    .join("");

  // hreflang: every version lists all versions including itself, plus x-default pointing at English.
  const alternates =
    o.origin && !o.noindex && o.altLocales && o.altLocales.length > 1
      ? o.altLocales
          .map((l) => `<link rel="alternate" hreflang="${LOCALE_META[l].hreflang}" href="${esc(o.origin + localizedPath(l, o.path))}">`)
          .join("\n") + (o.altLocales.includes("en") ? `\n<link rel="alternate" hreflang="x-default" href="${esc(o.origin + o.path)}">` : "")
      : "";
  const aiNote =
    loc === "en"
      ? ""
      : `<p class="aino">${esc(lt("This page was translated with AI and may contain mistakes. The English version is the reference."))} <a href="${available.has("en") ? o.path : "/"}" hreflang="en" lang="en">English</a></p>`;

  const html = `<!doctype html>
<html lang="${meta.htmlLang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
<meta name="description" content="${esc(o.description)}">
<meta name="robots" content="${o.noindex ? "noindex" : "index,follow,max-image-preview:large"}">
<meta name="theme-color" content="#fffbf5">
${url ? `<link rel="canonical" href="${esc(url)}">` : ""}
${alternates}
<link rel="icon" href="/favicon.ico" sizes="48x48">
<link rel="icon" href="/favicon-48.png" type="image/png" sizes="48x48">
<link rel="icon" href="/favicon-96.png" type="image/png" sizes="96x96">
<link rel="icon" href="/favicon.svg" type="image/svg+xml" sizes="any">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<meta property="og:site_name" content="${BRAND}">
<meta property="og:type" content="${o.ogType ?? "website"}">
<meta property="og:locale" content="${meta.ogLocale}">
<meta property="og:title" content="${esc(o.title)}">
<meta property="og:description" content="${esc(o.description)}">
${url ? `<meta property="og:url" content="${esc(url)}">` : ""}
${o.origin ? `<meta property="og:image" content="${esc(o.origin + OG_IMAGE.path)}">
<meta property="og:image:width" content="${OG_IMAGE.width}">
<meta property="og:image:height" content="${OG_IMAGE.height}">
<meta property="og:image:alt" content="${esc(OG_IMAGE.alt)}">
<meta name="twitter:image" content="${esc(o.origin + OG_IMAGE.path)}">` : ""}
<meta name="twitter:card" content="${o.origin ? "summary_large_image" : "summary"}">
<style>${CSS.replace(/\n/g, "")}</style>
${jsonLdScripts(o.jsonLd)}
</head>
<body data-page="${esc(o.id)}">
<header class="top"><div class="wrap bar">
<a class="logo" href="${lp("/")}">${LOGO}</a>
<nav class="dnav" aria-label="${esc(lt("Primary"))}">${dnav}</nav>
${langMenu}
<a class="btn pri dcta" href="${lp("/")}">${esc(lt("Check my IP"))}</a>
<details class="burger"><summary aria-label="${esc(lt("Open menu"))}">${BURGER}</summary><nav class="drawer" aria-label="${esc(lt("Mobile"))}">${drawer}</nav></details>
</div></header>
<main><div class="wrap">
${o.body}
${aiNote}
</div></main>
<footer><div class="wrap">
<div class="fgrid">
<div><a class="logo" href="${lp("/")}">${LOGO}</a><p style="margin-top:12px">${esc(lt("Fast, private network tools. Find your IP address, look up DNS and WHOIS records, test your speed and more."))}</p></div>
<div><h4>${esc(lt("Tools"))}</h4><ul>${footerTools}</ul></div>
<div><h4>${esc(lt("Learn"))}</h4><ul>${footerLearn}<li><a href="/learn"><b>${esc(lt("All articles →"))}</b></a></li></ul></div>
<div><h4>${esc(lt("About"))}</h4><ul><li><a href="${lp("/about")}">${esc(lt("About and methodology"))}</a></li><li><a href="/developers"${loc === "en" ? "" : ' hreflang="en" lang="en"'}>Free IP API</a></li><li><a href="${lp("/privacy")}">${esc(lt("Privacy"))}</a></li><li><a href="/sitemap.xml">${esc(lt("Sitemap"))}</a></li><li><a href="https://github.com/Ishant-Singh-Dev/ipcomet-frontend" rel="noopener">GitHub</a></li><li><a href="mailto:${CONTACT_EMAIL}">${esc(lt("Contact"))}</a></li><li><button type="button" class="linkbtn" data-consent="open">${esc(lt("Analytics choices"))}</button></li></ul><p style="margin-top:14px">${esc(lt("No ads. Analytics only if you accept."))}</p></div>
</div>
${footerLangs}
<p class="copy">${esc(lt("© {year} ipcomet. Served from the Cloudflare network, close to you.", { year: new Date().getUTCFullYear() }))}</p>
</div></footer>
<script src="/app.js" defer></script>
</body>
</html>`;
  return minify(html);
}

export const toolHeader = (h1: string, lead: string, crumb = h1, loc: Locale = "en") =>
  `<section class="phead"><p class="crumbs"><a href="${localizedPath(loc, "/")}">${esc(t(loc, "Home"))}</a> / ${esc(crumb)}</p><h1>${esc(h1)}</h1><p class="lead">${esc(lead)}</p></section>`;

export function faqSection(items: Faq[], heading?: string, loc: Locale = "en"): string {
  if (!items.length) return "";
  const list = items.map((f) => `<details class="faq"><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join("");
  return `<section class="sec"><h2>${esc(heading ?? t(loc, "Frequently asked questions"))}</h2><div class="faqs">${list}</div></section>`;
}

export const faqJsonLd = (items: Faq[]) =>
  items.length
    ? {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        mainEntity: items.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
      }
    : null;

export const breadcrumbJsonLd = (origin: string, trail: Array<[string, string]>) =>
  origin
    ? {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        itemListElement: trail.map(([name, path], i) => ({ "@type": "ListItem", position: i + 1, name, item: origin + path })),
      }
    : null;

/**
 * Guide cards. The guides are English only, so on a translated page the cards say so and link to the English guide.
 */
export const articleCards = (slugs?: string[], big = false, loc: Locale = "en") => {
  const list = slugs ? slugs.map((s) => ARTICLES.find((a) => a.slug === s)!).filter(Boolean) : ARTICLES;
  const lang = loc === "en" ? "" : ' hreflang="en" lang="en"';
  const readTime = (min: number) => (loc === "en" ? `${min} min read` : t(loc, "English guide · {n} min read", { n: min }));
  // "lg", not "big": .big is the speed-test readout and would turn the cards monospace.
  return `<div class="posts${big ? " lg" : ""}">${list
    .map((a) => `<a class="post" href="/learn/${a.slug}"${lang}><b>${esc(a.title)}</b><span>${esc(a.description)}</span><em>${readTime(a.readMin)}</em></a>`)
    .join("")}</div>`;
};

export const toolCards = (ids?: string[], loc: Locale = "en") => {
  const all = TOOLS.map((x) => localTool(x, loc));
  const list = ids ? ids.map((i) => all.find((x) => x.id === i)!).filter(Boolean) : all.filter((x) => x.id !== "ip");
  return `<div class="tools">${list.map((x) => `<a class="tool" href="${localizedPath(loc, x.path)}"><b>${esc(x.name)}</b><span>${esc(x.desc)}</span></a>`).join("")}</div>`;
};

export const appJsonLd = (origin: string, name: string, description: string, path: string, loc: Locale = "en") => ({
  "@context": "https://schema.org",
  "@type": "WebApplication",
  name,
  description,
  applicationCategory: "UtilitiesApplication",
  operatingSystem: "Any",
  browserRequirements: "Requires a modern web browser",
  inLanguage: LOCALE_META[loc].htmlLang,
  offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
  ...(origin ? { url: origin + localizedPath(loc, path) } : {}),
});
